package unsafemmap

import (
	"fmt"
	"unsafe"

	"github.com/Voskan/cnfgo/cnfrt"
)

// Cast returns the section in of data as a []T. The section length must be
// exactly in.Count elements of T. On little-endian platforms a suitably
// aligned section is returned without copying (the result aliases data);
// misaligned sections are copied. On big-endian platforms elements are
// decoded from their little-endian wire form into a new slice.
//
// T must be a pointer-free flat type whose layout has no implicit padding,
// such as the flat types generated by cmd/cnfgo.
func Cast[T any](data []byte, in cnfrt.SectionInfo) ([]T, error) {
	var zero T
	size := uint64(unsafe.Sizeof(zero))
	if size == 0 || in.Len != uint64(in.Count)*size {
		return nil, fmt.Errorf("%w: section kind %d tag %d holds %d bytes, want %d elements of %d bytes",
			cnfrt.ErrBoundsViolation, in.Kind, in.Tag, in.Len, in.Count, size)
	}
	if in.Off > uint64(len(data)) || in.Len > uint64(len(data))-in.Off {
		return nil, fmt.Errorf("%w: section kind %d tag %d out of bounds", cnfrt.ErrBoundsViolation, in.Kind, in.Tag)
	}
	if in.Count == 0 {
		return nil, nil
	}
	return castLE[T](data[in.Off:in.Off+in.Len:in.Off+in.Len], int(in.Count))
}

// String returns the section in of data as a string aliasing data.
func String(data []byte, in cnfrt.SectionInfo) string {
	if in.Len == 0 {
		return ""
	}
	return cnfrt.UnsafeSealBytes(data[in.Off : in.Off+in.Len : in.Off+in.Len])
}
